package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.domain.query.finance.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-outbox-retry：人工重试原子性、幂等、状态和审计。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.outbox-retry.real",matches="true") @EnabledIfSystemProperty(named="ar.outbox-retry.real.commit",matches="true")
class OutboxRetryRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;@Autowired OutboxRetryService service;@Autowired OutboxLeaseService leases;long scope;
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String name:List.of("V002__ar_audit.sql","V011__ar_outbox.sql","V012__ar_outbox_retry.sql")){var file=Path.of("../scratch/dbddl/"+name);if(Files.exists(file))for(String sql:Files.readString(file).split(";"))if(!sql.isBlank())jdbc.execute(sql);}scope=UUID.randomUUID().getMostSignificantBits()>>>1;actor();}
 @AfterEach void clear(){CurrentUser.clear();}
 void actor(){CurrentUser.set(new CurrentUser.Identity("retry-test",Set.of(scope),Set.of("ar:outbox:read","ar:outbox:retry")));}
 String key(){return UUID.randomUUID().toString();}
 long enqueue(String status){String key=key();jdbc.update("INSERT INTO oms_ar_lifecycle_event(event_type,occurred_at,actor,correlation_id,created_by,updated_by) VALUES('TEST',NOW(6),'retry-test',?,'retry-test','retry-test')",key);long event=jdbc.queryForObject("SELECT id FROM oms_ar_lifecycle_event WHERE correlation_id=?",Long.class,key);jdbc.update("INSERT INTO oms_ar_outbox(event_id,legal_entity_id,destination,payload,status,attempt_count,last_error,created_by,updated_by) VALUES(?,?,'FINANCE_EVENTS','{\"amount\":\"10.12\"}',?,3,'HTTP_503','retry-test','retry-test')",event,scope,status);return jdbc.queryForObject("SELECT id FROM oms_ar_outbox WHERE event_id=?",Long.class,event);}
 OutboxRetryRequest request(long id){return new OutboxRetryRequest(key(),scope,id,0L,"接收端恢复后重试");}
 OutboxRetryPageQuery query(long id){var q=new OutboxRetryPageQuery();q.setLegalEntityId(scope);q.setOutboxId(id);return q;}
 @Test @DisplayName("人工重试原子保存前后状态，重放不产生重复通知或审计")void retry(){long id=enqueue("DEAD");String payload=jdbc.queryForObject("SELECT payload FROM oms_ar_outbox WHERE id=?",String.class,id);var request=request(id);Long audit=service.retry(request);assertThat(audit).isNotNull();assertThat(service.retry(request)).isEqualTo(audit);var row=jdbc.queryForMap("SELECT * FROM oms_ar_outbox WHERE id=?",id);assertThat(row.get("status")).isEqualTo("PENDING");assertThat(((Number)row.get("attempt_count")).intValue()).isZero();assertThat(((Number)row.get("version")).longValue()).isEqualTo(1);assertThat(row.get("last_error")).isNull();assertThat(row.get("payload")).isEqualTo(payload);assertThat(jdbc.queryForObject("SELECT next_attempt_at<=NOW(6) FROM oms_ar_outbox WHERE id=?",Boolean.class,id)).isTrue();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_outbox WHERE legal_entity_id=?",Long.class,scope)).isEqualTo(1);var history=service.history(query(id));assertThat(history.total()).isEqualTo(1);var record=history.records().getFirst();assertThat(record.id()).isEqualTo(audit);assertThat(record.beforeStatus()).isEqualTo("DEAD");assertThat(record.beforeAttemptCount()).isEqualTo(3);assertThat(record.beforeLastError()).isEqualTo("HTTP_503");assertThat(record.afterStatus()).isEqualTo("PENDING");assertThat(record.afterAttemptCount()).isZero();assertThat(record.afterVersion()).isEqualTo(1);assertThat(record.createdBy()).isEqualTo("retry-test");assertThat(record.reason()).isEqualTo(request.reason());assertThatThrownBy(()->service.retry(new OutboxRetryRequest(request.requestKey(),scope,id,0L,"changed"))).isInstanceOf(ServiceException.class);}
 @Test @DisplayName("旧版本、待发送、发送中及已成功状态均拒绝重置")void states(){long id=enqueue("RETRY");var stale=new OutboxRetryRequest(key(),scope,id,99L,"stale");assertThatThrownBy(()->service.retry(stale)).isInstanceOf(ServiceException.class);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Long.class,stale.requestKey())).isZero();for(String status:List.of("PENDING","PROCESSING","SENT")){jdbc.update("UPDATE oms_ar_outbox SET status=?,lease_token=?,lease_until=CASE WHEN ?='PROCESSING' THEN DATE_ADD(NOW(6),INTERVAL 30 SECOND) ELSE NULL END,sent_time=CASE WHEN ?='SENT' THEN NOW(6) ELSE NULL END WHERE id=?",status,status.equals("PROCESSING")?key():null,status,status,id);assertThatThrownBy(()->service.retry(request(id))).isInstanceOf(ServiceException.class);}}
 @Test @DisplayName("权限、范围、原因和不存在记录拒绝")void permissions(){long id=enqueue("RETRY");CurrentUser.set(new CurrentUser.Identity("reader",Set.of(scope),Set.of("ar:outbox:read")));assertThatThrownBy(()->service.retry(request(id))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);actor();assertThatThrownBy(()->service.retry(new OutboxRetryRequest(key(),scope,id,0L," "))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.retry(new OutboxRetryRequest(key(),scope+1,id,0L,"scope"))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);assertThatThrownBy(()->service.retry(request(Long.MAX_VALUE))).isInstanceOf(ServiceException.class);CurrentUser.set(new CurrentUser.Identity("other",Set.of(scope+1),Set.of("ar:outbox:read","ar:outbox:retry")));var q=query(id);q.setLegalEntityId(scope+1);assertThatThrownBy(()->service.history(q)).isInstanceOf(ServiceException.class);assertThatThrownBy(()->service.retry(new OutboxRetryRequest(key(),scope+1,id,0L,"scope"))).isInstanceOf(ServiceException.class);}
 @Test @DisplayName("审计写入失败回滚状态和幂等记录")void rollback(){long id=enqueue("DEAD");var request=request(id);String constraint="test_retry_"+key().replace("-","");jdbc.execute("ALTER TABLE oms_ar_outbox_retry ADD CONSTRAINT "+constraint+" CHECK(outbox_id<>"+id+")");try{assertThatThrownBy(()->service.retry(request)).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("DEAD");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Long.class,request.requestKey())).isZero();}finally{jdbc.execute("ALTER TABLE oms_ar_outbox_retry DROP CHECK "+constraint);}assertThat(service.retry(request)).isNotNull();}
 @Test @DisplayName("两个不同请求同时重试同一版本只有一个成功")void concurrent()throws Exception{long id=enqueue("DEAD");var gate=new CountDownLatch(1);try(var executor=Executors.newFixedThreadPool(2)){Callable<Boolean> action=()->{actor();try{gate.await();try{return service.retry(request(id))!=null;}catch(ServiceException e){return false;}}finally{CurrentUser.clear();}};var a=executor.submit(action);var b=executor.submit(action);gate.countDown();assertThat(List.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}assertThat(service.history(query(id)).total()).isEqualTo(1);}
 @Test @DisplayName("重试后领取仍可幂等重放，历史不跟随当前状态变化")void replayAfterClaim(){long id=enqueue("RETRY");var request=request(id);Long audit=service.retry(request);assertThat(audit).isNotNull();assertThat(leases.claim(new OutboxClaimRequest(scope,key(),3,30))).isNotNull();assertThat(service.retry(request)).isEqualTo(audit);assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("PROCESSING");assertThat(service.history(query(id)).records().getFirst().afterStatus()).isEqualTo("PENDING");}
 @Test @DisplayName("多轮重试保留各轮计数与前后版本，分页不丢审计")void history(){long id=enqueue("DEAD");Long first=service.retry(request(id));String token=key();assertThat(leases.claim(new OutboxClaimRequest(scope,token,1,30))).isNotNull();assertThat(leases.finish(new OutboxFinishRequest(id,scope,token,false,"HTTP_500",1,60))).isTrue();long version=jdbc.queryForObject("SELECT version FROM oms_ar_outbox WHERE id=?",Long.class,id);Long second=service.retry(new OutboxRetryRequest(key(),scope,id,version,"second cycle"));var q=query(id);q.setSize(1);var page=service.history(q);assertThat(page.total()).isEqualTo(2);assertThat(page.records()).hasSize(1);assertThat(page.records().getFirst().id()).isEqualTo(second);assertThat(page.records().getFirst().beforeAttemptCount()).isEqualTo(1);assertThat(page.records().getFirst().beforeLastError()).isEqualTo("HTTP_500");q.setPage(2);assertThat(service.history(q).records().getFirst().id()).isEqualTo(first);q.setPage(Integer.MAX_VALUE);assertThat(service.history(q).records()).isEmpty();q.setSize(201);assertThatThrownBy(()->service.history(q)).isInstanceOf(ServiceException.class);CurrentUser.set(new CurrentUser.Identity("writer",Set.of(scope),Set.of("ar:outbox:retry")));assertThatThrownBy(()->service.history(query(id))).isInstanceOf(com.punjab.oms.ar.base.AccessDeniedException.class);}
 @Test @DisplayName("同请求并发提交返回同一审计ID")void concurrentReplay()throws Exception{long id=enqueue("DEAD");var request=request(id);var gate=new CountDownLatch(1);try(var executor=Executors.newFixedThreadPool(2)){Callable<Long> action=()->{actor();try{gate.await();return service.retry(request);}finally{CurrentUser.clear();}};var a=executor.submit(action);var b=executor.submit(action);gate.countDown();Long result=a.get(5,TimeUnit.SECONDS);assertThat(result).isNotNull();assertThat(b.get(5,TimeUnit.SECONDS)).isEqualTo(result);}assertThat(service.history(query(id)).total()).isEqualTo(1);}
 @Test @DisplayName("数据库拒绝非法审计后状态及版本")void constraints(){long id=enqueue("DEAD");Long audit=service.retry(request(id));assertThat(audit).isNotNull();assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox_retry SET after_attempt_count=1 WHERE id=?",audit)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));assertThatThrownBy(()->jdbc.update("UPDATE oms_ar_outbox_retry SET after_version=before_version WHERE id=?",audit)).isInstanceOf(org.springframework.dao.DataAccessException.class).satisfies(ex->assertThat(((java.sql.SQLException)ex.getCause()).getErrorCode()).isEqualTo(3819));}

}
